#include <algorithm>
#include <cstdio>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;
struct Fenwick {
    vector<int> tree;
    explicit Fenwick(int n) : tree(n + 1, 0) {}
    void add(int i) { for (; i < static_cast<int>(tree.size()); i += i & -i) ++tree[i]; }
    int sum(int i) const { int s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; }
};
void solve(istream& in, ostream& out) {
    int n; if (!(in >> n)) return;
    vector<pair<int,int>> a(n);
    for (int i = 0; i < n; ++i) { in >> a[i].first; a[i].second = i; }
    sort(a.begin(), a.end());
    vector<int> rank(n);
    for (int r = 0; r < n; ++r) rank[a[r].second] = r;
    Fenwick bit(n); int answer = 1;
    for (int k = 1; k <= n; ++k) {
        bit.add(rank[k - 1] + 1);
        answer = max(answer, k - bit.sum(k));
    }
    out << answer << '\n';
}
int main() {
    if (FILE* f = fopen("sort.in", "r")) { fclose(f); freopen("sort.in", "r", stdin); freopen("sort.out", "w", stdout); }
    ios::sync_with_stdio(false); cin.tie(nullptr); solve(cin, cout); return 0;
}
