#include <cstdio>
#include <functional>
#include <iostream>
#include <queue>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, m; if (!(in >> n >> m)) return;
    vector<vector<int>> observations(m);
    for (auto& list : observations) { int length; in >> length; list.resize(length); for (int& x : list) { in >> x; --x; } }
    auto graph = [&](int prefix, vector<vector<int>>& adj, vector<int>& degree) {
        adj.assign(n, {}); degree.assign(n, 0);
        for (int i = 0; i < prefix; ++i)
            for (int j = 1; j < static_cast<int>(observations[i].size()); ++j) {
                int u = observations[i][j - 1], v = observations[i][j];
                adj[u].push_back(v); ++degree[v];
            }
    };
    auto feasible = [&](int prefix) {
        vector<vector<int>> adj; vector<int> degree; graph(prefix, adj, degree);
        queue<int> available;
        for (int u = 0; u < n; ++u) if (degree[u] == 0) available.push(u);
        int visited = 0;
        while (!available.empty()) {
            int u = available.front(); available.pop(); ++visited;
            for (int v : adj[u]) if (--degree[v] == 0) available.push(v);
        }
        return visited == n;
    };
    int lo = 0, hi = m;
    while (lo < hi) { int mid = lo + (hi - lo + 1) / 2; if (feasible(mid)) lo = mid; else hi = mid - 1; }
    vector<vector<int>> adj; vector<int> degree; graph(lo, adj, degree);
    priority_queue<int, vector<int>, greater<int>> available;
    for (int u = 0; u < n; ++u) if (degree[u] == 0) available.push(u);
    int emitted = 0;
    while (!available.empty()) {
        int u = available.top(); available.pop();
        if (emitted++) out << ' ';
        out << u + 1;
        for (int v : adj[u]) if (--degree[v] == 0) available.push(v);
    }
    out << '\n';
}
int main() {
    if (FILE* f = fopen("milkorder.in", "r")) { fclose(f); freopen("milkorder.in", "r", stdin); freopen("milkorder.out", "w", stdout); }
    ios::sync_with_stdio(false); cin.tie(nullptr); solve(cin, cout); return 0;
}
