#include <algorithm>
#include <cstdio>
#include <iostream>
#include <limits>
#include <utility>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, required; if (!(in >> n >> required)) return;
    vector<pair<int,int>> cows(n);
    for (auto& cow : cows) in >> cow.first >> cow.second;
    auto feasible = [&](int threshold) {
        const long long unreachable = numeric_limits<long long>::lowest() / 4;
        vector<long long> dp(required + 1, unreachable); dp[0] = 0;
        for (auto [weight, talent] : cows) {
            vector<long long> next = dp;
            long long gain = 1000LL * talent - 1LL * threshold * weight;
            for (int s = 0; s <= required; ++s) if (dp[s] != unreachable) {
                int destination = min(required, s + weight);
                next[destination] = max(next[destination], dp[s] + gain);
            }
            dp.swap(next);
        }
        return dp[required] >= 0;
    };
    int lo = 0, hi = 1000000;
    while (lo < hi) { int mid = lo + (hi - lo + 1) / 2; if (feasible(mid)) lo = mid; else hi = mid - 1; }
    out << lo << '\n';
}
int main() {
    if (FILE* f = fopen("talent.in", "r")) { fclose(f); freopen("talent.in", "r", stdin); freopen("talent.out", "w", stdout); }
    ios::sync_with_stdio(false); cin.tie(nullptr); solve(cin, cout); return 0;
}
